import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.Base64;
import java.util.Map;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

public class DocumentIngestionConsumer {

    private static final String QUEUE_URL = System.getenv("SQS_QUEUE_URL");
    private static final String UPLOAD_DIR = "/data/uploads/";
    private static final Gson gson = new Gson();

    public static void main(String[] args) throws Exception {
        SqsClient sqs = SqsClient.create();
        System.out.println("Starting document ingestion consumer...");

        while (true) {
            ReceiveMessageRequest req = ReceiveMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .maxNumberOfMessages(10)
                .waitTimeSeconds(20)
                .build();

            for (Message msg : sqs.receiveMessage(req).messages()) {
                try {
                    processMessage(msg);
                    sqs.deleteMessage(DeleteMessageRequest.builder()
                        .queueUrl(QUEUE_URL)
                        .receiptHandle(msg.receiptHandle())
                        .build());
                } catch (Exception e) {
                    System.err.println("Error processing message: " + e.getMessage());
                }
            }
        }
    }

    private static void processMessage(Message msg) throws Exception {
        Map<String, String> payload = gson.fromJson(
            msg.body(), new TypeToken<Map<String, String>>(){}.getType());

        String filename = payload.get("filename");
        String content = payload.get("content");
        String callbackUrl = payload.get("callback_url");

        // Validate filename has an allowed extension
        if (!isAllowedExtension(filename)) {
            System.err.println("Rejected file with disallowed extension: " + filename);
            return;
        }

        // Decode and write file
        byte[] fileBytes = Base64.getDecoder().decode(content);
        Path targetPath = Paths.get(UPLOAD_DIR, filename);
        Files.createDirectories(targetPath.getParent());
        Files.write(targetPath, fileBytes);
        System.out.println("Written file: " + targetPath);

        // Notify callback endpoint with file metadata
        if (callbackUrl != null && !callbackUrl.isEmpty()) {
            notifyCallback(callbackUrl, filename, fileBytes.length);
        }
    }

    private static boolean isAllowedExtension(String filename) {
        String[] allowed = {".pdf", ".docx", ".xlsx", ".png", ".jpg", ".txt"};
        String lower = filename.toLowerCase();
        for (String ext : allowed) {
            if (lower.endsWith(ext)) return true;
        }
        return false;
    }

    private static void notifyCallback(String callbackUrl, String filename, int size) {
        try {
            URL url = new URL(callbackUrl);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("POST");
            conn.setRequestProperty("Content-Type", "application/json");
            conn.setDoOutput(true);
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);

            String json = String.format(
                "{\"filename\":\"%s\",\"size\":%d,\"status\":\"ingested\"}",
                filename, size);

            try (OutputStream os = conn.getOutputStream()) {
                os.write(json.getBytes());
            }

            int responseCode = conn.getResponseCode();
            if (responseCode == 200) {
                try (BufferedReader br = new BufferedReader(
                        new InputStreamReader(conn.getInputStream()))) {
                    String response = br.lines().reduce("", String::concat);
                    System.out.println("Callback response: " + response);
                }
            }
        } catch (Exception e) {
            System.err.println("Callback failed: " + e.getMessage());
        }
    }
}
